begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(421756909869504353)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TSegmentedGlass #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<div class="amc-TSegmentedGlass-scroller">',
'<div class="amc-TSegmentedGlass-track">',
'<span class="amc-TSegmentedGlass-thumb" aria-hidden="true"></span>',
'<ul class="amc-TSegmentedGlass-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>',
'</div>',
'</div>'))
,p_list_template_current=>'<li class="amc-TSegmentedGlass-item is-current"><a class="amc-TSegmentedGlass-link" href="#LINK#" aria-current="page" data-label="#TEXT_ESC_SC#"><span class="amc-TSegmentedGlass-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TSegmentedGlass-label">#TEXT#</span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TSegmentedGlass-item"><a class="amc-TSegmentedGlass-link" href="#LINK#" data-label="#TEXT_ESC_SC#"><span class="amc-TSegmentedGlass-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TSegmentedGlass-label">#TEXT#</span></a></li>'
,p_list_template_name=>'AMC Segmented Glass'
,p_internal_name=>'AMC_TPL_SEGMENTED_GLASS'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-segmented-glass.css'
,p_list_template_comment=>'List template for view switching and page-level navigation. Each entry is a real link with icon and label; the current entry gets aria-current=page. Segments share one width, and a raised glass thumb marks the current page and slides to the hovered or keyboard-focused segment without JavaScript. Lists longer than eight entries, and browsers without :has(), keep a static glass thumb on the current segment. The control scrolls horizontally when it is wider than its container. Template options: Icon only hides the labels visually, keeps them for screen readers and shows them as a tooltip on hover and focus; Stacked puts the icon above the label; Primary thumb fills the thumb with the primary color; Stretch spans the full width; Large raises the height. Under prefers-reduced-motion the thumb jumps without sliding; in forced-colors mode the current segment gets a system outline.'
);
end;
